#!/usr/bin/env python3
"""Independent CP21 continuation invariants and native validators.
No builder, case definitions or helpers are imported. Editorial review is a
separate agent-authored result; this script alone never certifies semantics.
"""
import argparse,collections,hashlib,json,subprocess,sys
from pathlib import Path
BASE=Path('work/cp21/STAGE_A_CP21_FORMAL_20261102.json')
BASE_SHA='0ccb219ab7acb7ec8142e35280dcdc89225062e96864e6707c1fb1d2cd8ae469'
FULL=Path('work/native/data/cards.full.json')
FULL_SHA='d22f0d4e39e035b9537b3e9abdf48abe6b7eb80f7e477e87aff1284f9e27e0d9'
IDENTITY=('source_row_index','story_id','candidate_id','headline_raw','primary_url','origin')
POOLS=('strict_passed_spec','candidate_review_pool','watchlist_context_pool','reject_or_support_only_pool','existing_reinforcement')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text())
def verify(path,native=False):
 assert sha(BASE)==BASE_SHA,'CP21 baseline hash changed'
 assert sha(FULL)==FULL_SHA,'LockedFull changed'
 b=read(BASE);n=read(path)
 assert len(b['decision_ledger'])==len(n['decision_ledger'])==1330,'Source count'
 assert len(b['promotion_reassessment_ledger'])==195 and len(b['strict_passed_spec'])==47
 assert n['promotion_reassessment_ledger'][:195]==b['promotion_reassessment_ledger'],'Prior formal history changed'
 assert n['strict_passed_spec'][:47]==b['strict_passed_spec'],'Prior Strict changed'
 oldformal={r['candidate_id'] for r in b['promotion_reassessment_ledger']}
 formal=[r['candidate_id'] for r in n['promotion_reassessment_ledger']]
 assert len(set(formal))==len(formal),'Duplicate formalSourceIDs'
 oldby={r['candidate_id']:r for r in b['decision_ledger']}
 newby={r['candidate_id']:r for r in n['decision_ledger']}
 assert len(oldby)==len(newby)==1330 and oldby.keys()==newby.keys()
 assert set(formal)<=newby.keys()
 newformal=set(formal)-oldformal
 changed=set()
 for i,(o,r) in enumerate(zip(b['decision_ledger'],n['decision_ledger'])):
  assert i==o['source_row_index']==r['source_row_index'],'Roworder changed'
  assert all(o.get(k)==r.get(k)for k in IDENTITY),(i,'Immutable identity changed')
  if o!=r:changed.add(r['candidate_id'])
  if r['candidate_id']in oldformal:assert o==r,(i,'Prior formal row changed')
 assert changed==newformal,{'changed_not_newformal':sorted(changed-newformal),'newformal_not_changed':sorted(newformal-changed)}
 partition={}
 for pool in POOLS:
  for r in n[pool]:
   sid=r['story_id'];assert sid not in partition,(sid,'Multiple final pools');partition[sid]=pool
 assert set(partition)==set(r['story_id']for r in n['decision_ledger'])
 strict_ids=set(r['story_id']for r in n['strict_passed_spec'])
 assert len(strict_ids)==len(n['strict_passed_spec']),'Strict source rows duplicate'
 for entry in n['promotion_reassessment_ledger'][195:]:
  sid=entry['candidate_id'];r=newby[sid]
  assert partition[r['story_id']]==r['stage_a_pool']==entry['after_pool'],(sid,'Formal/pool mismatch')
  assert entry['source_observation_preserved']is True
  assert entry['resolved']and entry['source_candidates'],(sid,'Missing substantive disposition/source')
  for flag in ('stage_b_authorized','accepted_facts_approved','canonical_card_write_allowed'):assert r.get(flag)is False,(sid,flag)
 # All previously formal membership is preserved as well as content.
 for pool in POOLS:
  before={r['story_id']:r for r in b[pool]if r['story_id']in oldformal}
  after={r['story_id']:r for r in n[pool]}
  for sid,r in before.items():assert sid in after and r==after[sid],(sid,'Prior emittedpool row changed')
 expected_pending=1330-len(formal)
 assert n['summary']['processed_priority_source_observations']==len(formal)
 assert n['summary']['unprocessed_editorial_observations']==expected_pending
 assert n['summary']['strict_passed_spec_count']==len(n['strict_passed_spec'])
 assert len(n['review_pool_resolution_ledger'])==1330-len(strict_ids)-len(n['existing_reinforcement'])
 newcounts=collections.Counter(partition[newby[s]['story_id']]for s in newformal)
 result={'invariant_status':'PASS','independent_semantic_status':'SEPARATE_AGENT_REVIEW_REQUIRED','baseline_sha256':BASE_SHA,'artifact_sha256':sha(path),'immutable_source_count':1330,'old_formal_unchanged':195,'old_strict_unchanged':47,'new_formal':len(newformal),'new_pool_counts':dict(newcounts),'cumulative_formal':len(formal),'strict_count':len(strict_ids),'pending':expected_pending,'changed_rows':sorted(newby[s]['source_row_index']for s in changed),'lockedFull_sha256':sha(FULL)}
 if native:
  outputs={}
  for name,mode in (('stage_artifact_contract_check.py','A'),('stage_lineage_contract_check.py','stage_a')):
   p=subprocess.run([sys.executable,'work/native/validation_scripts/'+name,mode,str(path.resolve())],capture_output=True,text=True,timeout=120)
   assert p.returncode==0 and 'PASS'in p.stdout and 'BLOCKED'not in p.stdout,(name,p.returncode,p.stdout,p.stderr)
   outputs[name]={'returncode':p.returncode,'stdout':p.stdout.strip()}
  result['native_contracts']=outputs
 return result
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('artifact',type=Path);p.add_argument('--native',action='store_true');p.add_argument('--out',type=Path);a=p.parse_args();r=verify(a.artifact,a.native);text=json.dumps(r,ensure_ascii=False,indent=2)+'\n'
 if a.out:a.out.write_text(text)
 print(text)

