if direct.exists():meta['local_direct_fetch_status']=json.loads(direct.read_text()).get('status')
receipt=x.get('independent_review_receipt')
if receipt:
 q=json.loads(Path(receipt).read_text());assert q['status']=='ORIGINAL_BODY_INDEPENDENTLY_READ'and q['url']==x['url'];assert q['reviewer']!=x['reviewer'];meta.update(independent_agent_verified=True,independent_review_receipt=receipt,independent_review_receipt_sha256=hashlib.sha256(Path(receipt).read_bytes()).hexdigest())
(folder/(key+'.web_evidence.json')).write_text(json.dumps(meta,ensure_ascii=False,indent=2));print(json.dumps({'key':key,'text_sha256':meta['captured_text_sha256'],'independent_verified':meta['independent_agent_verified']}))

